function biggestTable(favorite: number[]): number {
  const n = favorite.length;
  const path: number[] = [];
  const used = new Array(n).fill(false);
  let best = 0;
  const valid = (): boolean => {
    const k = path.length;
    for (let j = 0; j < k; j++) {
      const f = favorite[path[j]];
      if (path[(j + k - 1) % k] !== f && path[(j + 1) % k] !== f) return false;
    }
    return true;
  };
  const dfs = (): void => {
    if (path.length >= 2 && path.length > best && valid()) best = path.length;
    for (let p = 0; p < n; p++) {
      if (used[p]) continue;
      used[p] = true; path.push(p);
      dfs();
      path.pop(); used[p] = false;
    }
  };
  dfs();
  return best;
}

