            k = len(path)
            for j in range(k):
                f = favorite[path[j]]
                if path[j - 1] != f and path[(j + 1) % k] != f:
                    return False
            return True

        def dfs():
            nonlocal best
            if len(path) >= 2 and len(path) > best and valid():
                best = len(path)
            for p in range(n):
                if not used[p]:
                    used[p] = True
                    path.append(p)
                    dfs()
                    path.pop()
                    used[p] = False

        dfs()
        return best

