function biggestTable(favorite: number[]): number {
  const n = favorite.length;
  const indeg = new Array(n).fill(0);
  for (const f of favorite) indeg[f]++;
  const depth = new Array(n).fill(0);
  const queue: number[] = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);
  for (let h = 0; h < queue.length; h++) {
    const u = queue[h], v = favorite[u];
    depth[v] = Math.max(depth[v], depth[u] + 1);
    if (--indeg[v] === 0) queue.push(v);
  }
  let bestLoop = 0, pairTotal = 0;
  for (let i = 0; i < n; i++) {
    if (indeg[i] === 0) continue;
    let len = 0, u = i;
    while (indeg[u] !== 0) { indeg[u] = 0; len++; u = favorite[u]; } // mark loop as seen
    if (len === 2) pairTotal += 2 + depth[i] + depth[favorite[i]];
    else bestLoop = Math.max(bestLoop, len);
  }
  return Math.max(bestLoop, pairTotal);
}

