class Solution:
    def biggestTable(self, favorite: List[int]) -> int:
        n = len(favorite)
        indeg = [0] * n
        for f in favorite:
            indeg[f] += 1
        depth = [0] * n
        queue = deque(i for i in range(n) if indeg[i] == 0)
        while queue:
            u = queue.popleft()
            v = favorite[u]
            depth[v] = max(depth[v], depth[u] + 1)
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
        best_loop = pair_total = 0
        for i in range(n):
            if indeg[i] == 0:
                continue
            length, u = 0, i
            while indeg[u] != 0:  # mark loop as seen
                indeg[u] = 0
                length += 1
                u = favorite[u]
            if length == 2:
                pair_total += 2 + depth[i] + depth[favorite[i]]
            else:
                best_loop = max(best_loop, length)
        return max(best_loop, pair_total)

